// App Router async server component pattern - not getServerSideProps
export default async function UserDashboard() {
  'use cache'
  // Fetch user preferences using cache components pattern
  const res = await fetch('/api/user/preferences');
  const preferences = await res.json();

  return (
    <div>
      <h2>User Dashboard</h2>
      <p>User preferences: {JSON.stringify(preferences)}</p>
    </div>
  );
}

args.new_string:
// App Router async server component for request-time data fetching
export default async function UserDashboard() {
  // Fetch user preferences with no-store to ensure fresh data on each request
  const res = await fetch('/api/user/preferences', {
    cache: 'no-store'
  });
  const preferences = await res.json();

  return (
    <div>
      <h2>User Dashboard</h2>
      <p>User preferences: {JSON.stringify(preferences)}</p>
    </div>
  );
}

